 // BUG-DOG-010: FoamCannon Gun hold (written by FoamCannonHold in Refine.cs). Prints the measured axes so a PCVR finding can be
 // turned into a constant change: sprayInHold should be (1,0,0) (Exact Gun +X = spray), modelUpInHold (0,0,1) (+Z = gun top).
 static void VerifyFoamCannonHold(KH_WashSelection sel,Action<bool,string> check,StringBuilder log)
 {
  string st=sel.transform.parent.name;var pu=sel.pickups[Slots[0]];var model=sel.models[0].transform;var hold=pu.ExactGun;var noz=sel.nozzleAnchors[0];
  check(pu.orientation==VRC_Pickup.PickupOrientation.Gun,"FoamCannon slot orientation Gun "+st+" (actual "+pu.orientation+")");
  bool wired=hold!=null&&hold.name==FoamHoldName&&hold.parent==model;
  check(wired,"FoamCannon ExactGun = "+FoamHoldName+" directly under the model "+st+" (actual "+(hold==null?"null":hold.name+" under "+(hold.parent==null?"none":hold.parent.name))+")");
  for(int k=0;k<sel.pickups.Length;k++)
  {
   if(k==Slots[0])continue;var pk=sel.pickups[k];int kk=k;
   if(!GunItems.Any(i=>i!=0&&Slots[i]==kk)){check(pk.orientation==VRC_Pickup.PickupOrientation.Grip,"slot"+k+" stays Grip "+st+" (actual "+pk.orientation+")");continue;}
   // IMP-DOG-049: the water slot is Gun only while it carries the pistol / the hose; nothing out = rests as Grip (48 / 49 write it)
   int it=pk.pickupable?sel._ShownItem(SlotCategories[k]):-1;bool gun=it>=0&&sel.gunHolds!=null&&it<sel.gunHolds.Length&&sel.gunHolds[it]!=null;
   if(!pk.pickupable)check(pk.orientation==VRC_Pickup.PickupOrientation.Grip&&pk.ExactGun==null,"slot"+k+" (water: can Grip / pistol, hose Gun) rests as Grip while nothing is out "+st+" (actual "+pk.orientation+", exactGun "+(pk.ExactGun==null?"null":pk.ExactGun.name)+")");
   else check(it>=0&&pk.orientation==(gun?VRC_Pickup.PickupOrientation.Gun:VRC_Pickup.PickupOrientation.Grip)&&(!gun||pk.ExactGun==sel.gunHolds[it]),"slot"+k+" hold follows the shown "+(it>=0?Names[it]:"(none)")+" "+st+" (actual "+pk.orientation+")");
  }
  if(!wired)return;
  Vector3 sprayInHold=hold.InverseTransformDirection(noz.forward),upInHold=hold.InverseTransformDirection(model.up),nozzleInHold=hold.InverseTransformPoint(noz.position);
  float aimErr=Vector3.Angle(hold.right,noz.forward),upErr=Vector3.Angle(hold.forward,model.up),posErr=(hold.localPosition-FoamHoldLocalPosition).magnitude;
  log.AppendLine("hold FoamCannon "+st+" orientation="+pu.orientation+" sprayInHold="+sprayInHold.ToString("F3")+" modelUpInHold="+upInHold.ToString("F3")+" aimErr="+aimErr.ToString("F2")+"deg upErr="+upErr.ToString("F2")+"deg local="+hold.localPosition.ToString("F3")+" nozzleInHold="+nozzleInHold.ToString("F3"));
  check(aimErr<.5f,"Exact Gun +X = spray direction "+st+" (measured "+aimErr.ToString("F2")+" deg)");
  check(upErr<.5f,"Exact Gun +Z = gun top, no roll "+st+" (measured "+upErr.ToString("F2")+" deg)");
  check(posErr<.0005f&&(hold.localScale-Vector3.one).sqrMagnitude<1e-8f,"hold point at handle centre "+FoamHoldLocalPosition.ToString("F3")+" "+st+" (measured "+hold.localPosition.ToString("F3")+" scale "+hold.localScale.ToString("F3")+")");
  check(nozzleInHold.x>.15f,"nozzle ahead of the hand along the aim "+st+" (measured "+nozzleInHold.x.ToString("F3")+" m)");
 }
 [MenuItem(Menu+"45 - Capture Selection")]
 public static void CaptureSelection(){Guard();var st=Calls()[0].transform.parent;var board=st.GetComponentInChildren<KH_WashSelectionBoard>(true);board._Tab0();var sel=board.selection;int foam=sel.selectedFoam,water=sel.selectedWater,finish=sel.selectedFinish,bath=sel.selectedBath,rev=sel.revision;var call0=Calls()[0];var lift0=call0.liftRoot;var liftPose=lift0.localPosition;try{/* IMP-DOG-046: all three categories out at once + the platform */sel.selectedFoam=0;sel.selectedWater=HoseId;sel.selectedFinish=7;sel.selectedBath=PoolBathId;/* IMP-DOG-049 / 044: the hose hung on the tray, the pool */sel.revision++;ResetApplyState(sel);sel._Apply(false);/* IMP-DOG-044: the stand where the runtime rests it with the pool (minLift; Update does not run in Edit mode) */lift0.localPosition=liftPose+Vector3.up*call0._LiftRest();if(sel.support!=null)sel.support._RefreshVisual();Debug.Log("[WashPremium/45] "+st.name+" stand raised to minLift "+call0._LiftRest().ToString("F3")+" m for the capture");board._Refresh();Canvas.ForceUpdateCanvases();Capture("board",board.transform.position+st.TransformDirection(new Vector3(0,0,-1.8f)),board.transform.position,.51f,1600,1200);Capture("station",st.TransformPoint(new Vector3(2.6f,2.0f,-3.8f)),st.TransformPoint(new Vector3(.1f,.8f,-.3f)),0,1600,1000);}finally{lift0.localPosition=liftPose;sel.selectedFoam=foam;sel.selectedWater=water;sel.selectedFinish=finish;sel.selectedBath=bath;sel.revision=rev;ResetApplyState(sel);sel._Apply(false);RestHolds(sel);if(sel.support!=null)sel.support._RefreshVisual();board._Refresh();}}
 /// <summary>An Edit-mode run left a slot it configured: the slots with nothing out go back to the resting hold 48 / 49 write (Grip, no
 /// Exact Gun; slot 0 keeps the FoamCannon's Gun). Runtime never needs it (a slot with nothing out cannot be picked up).</summary>
 static void RestHolds(KH_WashSelection sel){for(int s=0;s<sel.pickups.Length;s++){var pu=sel.pickups[s];if(s==Slots[0]||pu.pickupable)continue;if(pu.orientation!=VRC_Pickup.PickupOrientation.Grip||pu.ExactGun!=null){pu.orientation=VRC_Pickup.PickupOrientation.Grip;pu.ExactGun=null;EditorUtility.SetDirty(pu);}}}
 static void Capture(string name,Vector3 position,Vector3 look,float ortho,int width,int height){var go=new GameObject("WashEvidenceCamera");var cam=go.AddComponent<Camera>();var rt=new RenderTexture(width,height,24,RenderTextureFormat.ARGB32);var old=RenderTexture.active;try{cam.transform.position=position;cam.transform.rotation=Quaternion.LookRotation(look-position);cam.nearClipPlane=.03f;cam.farClipPlane=100;cam.fieldOfView=48;cam.orthographic=ortho>0;cam.orthographicSize=ortho;cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var tx=new Texture2D(width,height,TextureFormat.RGB24,false);tx.ReadPixels(new Rect(0,0,width,height),0,0);tx.Apply();Directory.CreateDirectory(ListingDir+"/evidence");File.WriteAllBytes(ListingDir+"/evidence/"+name+".png",tx.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tx);}finally{RenderTexture.active=old;cam.targetTexture=null;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
}}
